for _st, _a in A.items():  # fill link and filing date from the FAC data, never by hand
    if _a.pop("fac", False):
        _r = FAC_REPORTS[_st]
        _a["url"] = FAC + _r["report_id"]
        _a["date"] = _dt.date.fromisoformat(_r["accepted"]).strftime("%b %-d, %Y")

if __name__ == "__main__":
    import json, os, re
    here = os.path.dirname(os.path.abspath(__file__))
    q = json.load(open(os.path.join(here, "data", "states", "auditors", "questioned.json")))
    bad = 0
    for st, a in sorted(A.items()):
        if st in q and a["url"].startswith(FAC):
            rid = a["url"][len(FAC):]
            if rid != q[st]["report_id"]:
                print(st, "REPORT ID MISMATCH", rid, "vs", q[st]["report_id"]); bad += 1
        if not a["check"]:
            continue
        p = os.path.join(here, "data", "states", "auditors", "raw", a.get("raw") or f"fac/{st}.txt")
        t = re.sub(r"\s+", " ", open(p, encoding="utf-8", errors="ignore").read()).replace("’", "'")
        if re.sub(r"\s+", " ", a["check"]) not in t:
            print(st, "CHECK TEXT NOT FOUND:", a["check"]); bad += 1
    print(len(A), "states,", bad, "problems")
